suppressMessages({library(dplyr);library(bundeslaendeR)}); options(width=250)
u <- readRDS("data/state_elections/final/state_unharm.rds"); w <- readRDS("data/state_elections/final/ltw_wkr_unharm.rds"); h<-readRDS("data/state_elections/final/state_harm_25.rds")
x <- u %>% filter(state=="11", election_year==2021)
P <- c("spd","cdu","gruene","linke_pds","afd","fdp","other")
g <- sapply(P, function(p) round(100*x[[p]],2)); print(g)
wz <- w %>% filter(state=="11", election_year==2021) %>% group_by(stimme) %>% summarise(across(all_of(P), ~round(100*sum(.x*valid_votes,na.rm=T)/sum(valid_votes),2))); print(wz)
print(as.data.frame(ltw_elections) %>% filter(state=="BE", election_date==as.Date("2021-09-26")) %>% arrange(desc(party_vote_count)) %>% select(partyname_short,party_vote_count,party_vshare) %>% head(8))
cat("h25 BE 2021 gruene:", round(100*h$gruene[h$state=="11"&h$election_year==2021],2), " valid", h$valid_votes[h$state=="11"&h$election_year==2021], "\n")
cat("unharm valid_votes:", x$valid_votes, " eligible", x$eligible_voters, "\n")
